async def act(page):
    """
    - Prefer the knowledge-base helper create_curated_collection_by_search(...) to perform the visible-site search for 'Collector'.
    - If that helper returns a result list, attempt to click the first visible result (role='main' -> first role='article' -> first role='link')
      and return the helper's result unchanged.
    - If the helper fails or returns None, perform a manual flow from the current page state:
      * Dismiss any visible dialog (role='dialog') that might block the UI
      * Locate a search input (prefer inside role='complementary', else global role='searchbox' or 'textbox')
      * Fill it with 'Collector' and activate the search (prefer clicking a Search button inside complementary, else press Enter)
      * Wait for role='main' results and click the first result (article -> link)
    Notes:
    - All .nth() indexing is guarded by .count() checks to avoid indexing errors.
    - Clicking a link expected to navigate away is performed as the last DOM-modifying action.
    """
    results = None

    # Try the knowledge-base helper first (preferred when available).
    try:
        results = await create_curated_collection_by_search(page, "Collector")
    except Exception:
        results = None

    async def click_first_result_from_main():
        """Click the first article->link inside role='main'. Return True if a click was performed."""
        main = page.get_by_role("main")
        try:
            await main.wait_for(state="visible", timeout=3000)
        except Exception:
            # continue even if wait_for times out
            pass

        # Initialize defaults to avoid unbound-variable issues
        articles = main.get_by_role("article")
        article_count = 0
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

        if article_count > 0:
            first_article = articles.nth(0)

            links = first_article.get_by_role("link")
            link_count = 0
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0

            if link_count > 0:
                # Click the first link inside the first article (last action)
                await links.nth(0).click()
                return True

            # If no explicit link, try clicking the article itself
            try:
                await first_article.click()
                return True
            except Exception:
                return False

        # Fallback: try first link directly under main
        main_links = main.get_by_role("link")
        main_link_count = 0
        try:
            main_link_count = await main_links.count()
        except Exception:
            main_link_count = 0

        if main_link_count > 0:
            await main_links.nth(0).click()
            return True

        return False

    # If the helper returned results, try to click the first visible result and return the results unchanged.
    if results is not None:
        try:
            await click_first_result_from_main()
        except Exception:
            # ignore click failures but still return the API result unchanged
            pass
        return results

    # Manual fallback flow: dismiss dialog/overlay if present.
    try:
        dialog_count = await page.get_by_role("dialog").count()
    except Exception:
        dialog_count = 0

    if dialog_count > 0:
        dialog = page.get_by_role("dialog").nth(0)
        closed = False
        close_labels = ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]
        for lbl in close_labels:
            try:
                btns = dialog.get_by_role("button", name=lbl)
                if await btns.count() > 0:
                    try:
                        # Use full path: dialog.get_by_role(...).get_by_role(...) is already used
                        await btns.nth(0).click()
                        closed = True
                        break
                    except Exception:
                        closed = False
            except Exception:
                continue

        if not closed:
            # As a last resort try the first button inside the dialog
            try:
                btns_all = dialog.get_by_role("button")
                if await btns_all.count() > 0:
                    await btns_all.nth(0).click()
            except Exception:
                pass
    else:
        # Try page-level close buttons in case the popup doesn't expose a dialog role
        close_labels = ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]
        for lbl in close_labels:
            try:
                btns = page.get_by_role("button", name=lbl)
                if await btns.count() > 0:
                    try:
                        await btns.nth(0).click()
                        break
                    except Exception:
                        continue
            except Exception:
                continue

    # Locate search input: prefer inside complementary region
    search_input = None
    comp = None
    try:
        comp_count = await page.get_by_role("complementary").count()
    except Exception:
        comp_count = 0

    if comp_count > 0:
        comp = page.get_by_role("complementary").nth(0)
        try:
            if await comp.get_by_role("searchbox").count() > 0:
                search_input = comp.get_by_role("searchbox").nth(0)
            elif await comp.get_by_role("textbox").count() > 0:
                search_input = comp.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None

    if search_input is None:
        try:
            if await page.get_by_role("searchbox").count() > 0:
                search_input = page.get_by_role("searchbox").nth(0)
            elif await page.get_by_role("textbox").count() > 0:
                # Prefer a textbox whose accessible name contains 'search'
                textbox_count = await page.get_by_role("textbox").count()
                chosen = None
                for i in range(textbox_count):
                    tb = page.get_by_role("textbox").nth(i)
                    try:
                        aria = await tb.get_attribute("aria-label")
                    except Exception:
                        aria = None
                    try:
                        title = await tb.get_attribute("title")
                    except Exception:
                        title = None
                    if (aria and "search" in aria.lower()) or (title and "search" in title.lower()):
                        chosen = tb
                        break
                if chosen is not None:
                    search_input = chosen
                elif textbox_count > 0:
                    search_input = page.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None

    # If still no search input, try pragmatic direct search results URL and click first result there
    if search_input is None:
        try:
            await page.goto('/?s=Collector')
        except Exception:
            pass
        try:
            await page.get_by_role("main").wait_for(state="visible", timeout=5000)
        except Exception:
            try:
                await page.wait_for_load_state('networkidle')
            except Exception:
                pass
        try:
            await click_first_result_from_main()
        except Exception:
            pass
        return []

    # Fill the search input
    try:
        await search_input.fill("Collector")
    except Exception:
        try:
            await search_input.type("Collector")
        except Exception:
            pass

    # Activate the search: prefer Search button inside complementary region
    activated = False
    if comp is not None:
        try:
            # button whose visible name includes 'search'
            search_button = comp.get_by_role("button", name="search")
            if await search_button.count() > 0:
                await search_button.nth(0).click()
                activated = True
            else:
                # fallback to first button inside complementary
                all_buttons = comp.get_by_role("button")
                if await all_buttons.count() > 0:
                    await all_buttons.nth(0).click()
                    activated = True
        except Exception:
            activated = False

    if not activated:
        try:
            global_search = page.get_by_role("button", name="search")
            if await global_search.count() > 0:
                await global_search.nth(0).click()
                activated = True
        except Exception:
            activated = False

    if not activated:
        try:
            await search_input.press("Enter")
        except Exception:
            pass

    # Wait for results in role='main'
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    # Click the first result (last action)
    try:
        await click_first_result_from_main()
    except Exception:
        pass

    # Manual fallback has no KB API response to forward, return empty list
    return []

